<script setup>
import {computed,ref,watch,onMounted,onBeforeUnmount,nextTick} from 'vue'
import Icon from '../Icon.vue'
import {isDemo} from '../service'
import {request} from '../native/client'
const nativePlus=ref(false),checkout=ref(null)
async function quoteStudy(){try{checkout.value=await request('owner_pricing','quote',{product:'Study Space'})}catch(e){error.value=e.message}}
request('owner_pricing','entitlements').then(x=>nativePlus.value=!!x['Study Space']).catch(()=>{})
import StudyScene from './StudyScene.vue'
import PersonalTools from './PersonalTools.vue'
import {videoBackgrounds} from './backgrounds'
import {createTimer,restoreTimer,startTimer,pauseTimer,displayedTime,elapsedTime,isFinished,formatTimer,hasStudyPlus} from './timer'
import {createStudyAudio} from './audio'
import {readAppearance,palettes,encouragements} from './appearance'
const props=defineProps({member:Object,standalone:Boolean})
const spaceRoot=ref(null),tab=ref('focus'),film=ref(''),video=ref(null),filmError=ref(''),reduced=ref(matchMedia('(prefers-reduced-motion: reduce)').matches)
const activeFilm=computed(()=>videoBackgrounds.find(v=>v.id===film.value))
async function playFilm(){await nextTick();if(!video.value)return;if(quiet.value||reduced.value||document.hidden){video.value.pause();return}try{await video.value.play()}catch{filmError.value='Playback paused. Use Resume scene to start it.'}}
function selectFilm(item){if(!plus.value){upgrade.value=true;return}film.value=item.id;filmError.value='';quiet.value=false;reduced.value=false;playFilm()}
async function fullScreen(){if(immersive.value){if(document.fullscreenElement)await document.exitFullscreen();immersive.value=false;return}tab.value='focus';immersive.value=true;await nextTick();try{await spaceRoot.value.requestFullscreen()}catch{/* Focus view is the fallback on browsers without Fullscreen API. */}}
function fullscreenChanged(){if(!document.fullscreenElement)immersive.value=false}
function toolNavigate(value){if(value==='schedule')emit('navigate','schedule');else tab.value=value}
const emit=defineEmits(['notify','plans','navigate'])
const profileStyle=readAppearance(props.member.name,isDemo)
const key='sisu-study-v1:'+props.member.name
let saved={};try{saved=JSON.parse(localStorage.getItem(key))||{}}catch{}
if(videoBackgrounds.some(v=>v.id===saved.film))film.value=saved.film
const timer=ref(restoreTimer(saved.timer)),now=ref(Date.now()),minutes=ref(Math.round(timer.value.duration/60000)),topic=ref(String(saved.topic||'').slice(0,80)),theme=ref(['calm','cute','dark'].includes(saved.theme)?saved.theme:(profileStyle.mode==='dark'?'dark':'calm')),wallpaper=ref(['garden','blossom','rainy','night'].includes(saved.wallpaper)?saved.wallpaper:'garden'),entitlement=ref(saved.entitlement||null),sessions=ref(Array.isArray(saved.sessions)?saved.sessions.slice(-30):[])
const quiet=ref(!!saved.quiet),immersive=ref(false),upgrade=ref(false),sound=ref('piano'),playing=ref(false),volume=ref(.25),audioBusy=ref(false),message=ref(''),error=ref(''),recorded=ref(!!saved.recorded)
const upgradeDialog=ref(null)
const quotesVisible=ref(saved.quotesVisible!==false),quotePaused=ref(false),quoteIndex=ref(0)
const quoteText=computed(()=>encouragements[quoteIndex.value%encouragements.length])
const studyAccent=computed(()=>{const p=palettes.find(p=>p.id===profileStyle.accent)||palettes[0];return dark.value?p.dark:p.color})
const audio=createStudyAudio();let interval,quoteInterval,returnFocus
const plus=computed(()=>{if(!isDemo)return nativePlus.value;if(!hasStudyPlus(entitlement.value,now.value))return false;if(!props.standalone)return true;try{return JSON.parse(localStorage.getItem('sisu-card-trial:'+props.member.name))?.expires>now.value}catch{return false}}),dark=computed(()=>theme.value==='dark'),digits=computed(()=>formatTimer(displayedTime(timer.value,now.value)))
const wallpapers=[{id:'garden',title:'Quiet garden',detail:'A little room to grow',premium:false},{id:'blossom',title:'Blossom desk',detail:'Soft skies, small joys',premium:true},{id:'rainy',title:'Rainy window',detail:'Your cozy corner',premium:true},{id:'night',title:'Moonlit mountains',detail:'A peaceful night',premium:true}]
const total=computed(()=>Math.round(sessions.value.filter(s=>s.day===new Date().toLocaleDateString('en-CA')).reduce((a,s)=>a+s.seconds,0)/60))
function persist(){try{localStorage.setItem(key,JSON.stringify({timer:timer.value,topic:topic.value,theme:theme.value,wallpaper:wallpaper.value,film:film.value,entitlement:entitlement.value,sessions:sessions.value,quiet:quiet.value,recorded:recorded.value,quotesVisible:quotesVisible.value}))}catch{error.value='Your browser could not save study preferences. Free up local storage and try again.'}}
function stopAudio(){audio.stop();playing.value=false}
function logSession(){if(recorded.value||timer.value.mode==='break')return;const seconds=Math.floor(elapsedTime(timer.value)/1000);if(seconds>=1){sessions.value.push({day:new Date().toLocaleDateString('en-CA'),seconds,topic:topic.value||'A little focused time'});sessions.value=sessions.value.slice(-30)}recorded.value=true}
function finish(){timer.value=pauseTimer(timer.value);logSession();stopAudio();message.value=timer.value.mode==='break'?'Break complete. Ready when you are.':'A little progress, well done. Make room for a break.';persist()}
function tick(){if(document.hidden)video.value?.pause();now.value=Date.now();if(isFinished(timer.value,now.value))finish();if(!plus.value){film.value='';if(playing.value)stopAudio();if(theme.value==='cute')theme.value='calm';if(wallpaper.value!=='garden')wallpaper.value='garden'}}
function begin(){error.value='';message.value='';if(timer.value.mode!=='stopwatch'&&elapsedTime(timer.value)>=timer.value.duration){timer.value=createTimer(timer.value.mode,minutes.value);recorded.value=false}timer.value=startTimer(timer.value);now.value=Date.now();persist()}
function pause(){timer.value=pauseTimer(timer.value);stopAudio();message.value='Paused. Take the time you need.';persist()}
function reset(){timer.value=createTimer(timer.value.mode,minutes.value);recorded.value=false;message.value='Timer reset.';stopAudio();persist()}
function chooseMode(mode){if(timer.value.running)return;timer.value=createTimer(mode,mode==='break'?5:minutes.value);if(mode==='break')minutes.value=5;recorded.value=false;message.value='';persist()}
function setMinutes(value){if(timer.value.running)return;try{const next=createTimer(timer.value.mode,Number(value));minutes.value=Number(value);timer.value=next;recorded.value=false;message.value='';error.value='';persist()}catch(e){error.value=e.message}}
function end(){timer.value=pauseTimer(timer.value);logSession();stopAudio();message.value='Session saved. Your time belongs to you.';timer.value=createTimer(timer.value.mode,minutes.value);recorded.value=false;persist()}
function chooseWallpaper(w){film.value='';if(w.premium&&!plus.value){upgrade.value=true;return}wallpaper.value=w.id;if(w.id==='night')theme.value='dark';persist()}
function chooseTheme(value){if(value==='cute'&&!plus.value){upgrade.value=true;return}theme.value=value;persist()}
function activate(){if(!isDemo)return;entitlement.value={product:'study_plus',expiresAt:Date.now()+30*86400000};upgrade.value=false;persist();window.dispatchEvent(new Event('sisu-appearance'));emit('notify','Study Plus unlocked for 30 days in this browser demo. No payment or renewal was created.')}
function endPreview(){entitlement.value=null;tick();persist();window.dispatchEvent(new Event('sisu-appearance'));message.value='Study Plus preview ended. Your free timer and study history are still here.'}
async function toggleAudio(){if(playing.value){stopAudio();return}if(!plus.value){upgrade.value=true;return}audioBusy.value=true;try{playing.value=await audio.play(sound.value,volume.value);error.value=''}catch{error.value='Your browser could not start audio. Try Play again or use silent study.'}finally{audioBusy.value=false}}
function changeSound(){stopAudio()}
function keydown(e){if(e.key==='Escape'){if(upgrade.value)upgrade.value=false;else immersive.value=false}if(e.key==='Tab'&&upgrade.value){const items=[...upgradeDialog.value.querySelectorAll('button:not([disabled]),a[href],input,select,textarea')];const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}}
watch(upgrade,async value=>{if(value){returnFocus=document.activeElement;await nextTick();upgradeDialog.value?.querySelector('button')?.focus()}else returnFocus?.focus()})
watch(volume,value=>audio.volume(value))
watch(quiet,playFilm)
watch(tab,value=>{if(value!=='focus')video.value?.pause();else playFilm()})
watch([topic,quiet,quotesVisible,film],persist)
watch(immersive,value=>document.body.classList.toggle('study-immersive',value))
onMounted(()=>{document.addEventListener('fullscreenchange',fullscreenChanged);document.addEventListener('visibilitychange',playFilm);tick();interval=setInterval(tick,500);quoteInterval=setInterval(()=>{if(!quotePaused.value&&!document.hidden)quoteIndex.value++},90000);document.addEventListener('visibilitychange',tick);document.addEventListener('keydown',keydown)})
onBeforeUnmount(()=>{document.removeEventListener('fullscreenchange',fullscreenChanged);document.removeEventListener('visibilitychange',playFilm);if(document.fullscreenElement===spaceRoot.value)document.exitFullscreen().catch(()=>{});persist();clearInterval(interval);clearInterval(quoteInterval);document.removeEventListener('visibilitychange',tick);document.removeEventListener('keydown',keydown);document.body.classList.remove('study-immersive');audio.dispose()})
</script>
<template><div ref="spaceRoot" class="study-space" :class="[theme,{immersive}]" :style="{'--study-accent':studyAccent}"><div v-if="standalone&&!plus" class="study-premium-gate"><Icon name="Sparkles" :size="36"/><h2>Your own little sanctuary.</h2><p>Study Room is your premium space for calm focus, gentle sounds and living scenery.</p><button class="study-start" @click="upgrade=true">View Study Room access</button></div><div class="study-heading"><div><span class="eyebrow">A LITTLE SPACE, JUST FOR YOU</span><h1>Settle in. Let’s study.</h1><p>No rush. Find your focus, one little moment at a time.</p></div><button class="study-button" @click="fullScreen"><Icon :name="immersive?'Minimize':'Maximize'" :size="17"/>{{immersive?'Exit full screen':'Full screen'}}</button></div>
<nav v-if="!immersive&&!standalone" class="study-sections" aria-label="Study Space tools"><button v-for="item in [{id:'focus',label:'My sanctuary',icon:'Leaf'},{id:'todo',label:'To-do',icon:'CheckCheck'},{id:'journal',label:'Journal',icon:'NotebookPen'},{id:'unlock',label:'Unlock me',icon:'Sparkles'}]" :class="{chosen:tab===item.id,'unlock-glow':item.id==='unlock'}" :aria-pressed="tab===item.id" @click="tab=item.id"><Icon :name="item.icon" :size="16"/>{{item.label}}</button></nav><PersonalTools v-if="tab!=='focus'" :key="member.name" :member="member" :tab="tab" :plus="plus" @studyplus="upgrade=true" @navigate="toolNavigate"/><div v-show="tab==='focus'" class="study-grid"><section class="study-canvas" :class="[wallpaper,{'has-film':!!activeFilm}]" aria-label="Study timer"><StudyScene :wallpaper="wallpaper" :dark="dark" :quiet="quiet"/><video v-if="activeFilm" ref="video" :key="activeFilm.id" class="study-film" :src="activeFilm.src" muted loop playsinline preload="metadata" aria-hidden="true" @canplay="playFilm" @error="filmError='This scene could not load. Choose another scene or a still wallpaper.';film=''"></video><div v-if="activeFilm" class="film-shade"></div><div class="study-timer-content"><span class="study-pill"><Icon name="Sprout" :size="13"/>YOUR TIME TO GROW</span><label class="study-topic"><span class="sr-only">What are you working on?</span><input v-model="topic" maxlength="80" placeholder="What are you working on?"/></label><div class="study-modes" aria-label="Timer mode"><button v-for="mode in [{id:'focus',label:'Focus timer'},{id:'stopwatch',label:'Stopwatch'},{id:'break',label:'Take a break'}]" :aria-pressed="timer.mode===mode.id" :disabled="timer.running" @click="chooseMode(mode.id)">{{mode.label}}</button></div><div class="study-clock" role="timer" aria-live="off" :aria-label="(timer.mode==='stopwatch'?'Time studied ':'Time remaining ')+digits">{{digits}}</div><p class="study-clock-caption">{{timer.running?'One thing at a time. You’ve got this.':timer.elapsed?'Paused. Breathe a little.':'A fresh start is a small, beautiful thing.'}}</p><div v-if="timer.mode!=='stopwatch'" class="study-duration"><button v-for="n in [5,25,45,60]" :disabled="timer.running" :class="{chosen:timer.duration===n*60000}" @click="setMinutes(n)">{{n}} min</button><label><span class="sr-only">Custom focus minutes</span><input :value="minutes" type="number" min="1" max="180" :disabled="timer.running" aria-label="Custom focus minutes" @input="setMinutes($event.target.value)"><small>min</small></label></div><div class="study-timer-actions"><button class="study-start" @click="timer.running?pause():begin()"><Icon :name="timer.running?'Pause':'Play'" :size="20"/>{{timer.running?'Pause':timer.elapsed?'Resume':'Start studying'}}</button><button class="study-round" @click="reset" aria-label="Reset study timer" title="Reset timer"><Icon name="RotateCcw" :size="19"/></button><button v-if="timer.elapsed||timer.running" class="study-round" @click="end" aria-label="Save and finish study session" title="Save and finish"><Icon name="Check" :size="19"/></button></div><p class="study-status" role="status">{{message}}</p><div v-if="quotesVisible" class="study-quote"><Icon name="HeartHandshake" :size="17"/><p>{{quoteText}}</p><div><button :aria-pressed="quotePaused" @click="quotePaused=!quotePaused">{{quotePaused?'Resume quotes':'Pause quotes'}}</button><button @click="quoteIndex++">Another thought</button><button @click="quotesVisible=false">Hide</button></div></div><button v-else class="study-link" @click="quotesVisible=true">Show gentle encouragement</button></div><div class="study-canvas-footer"><span><Icon name="Leaf" :size="14"/>{{activeFilm?activeFilm.title:'A quiet moment with SOUL'}}</span><button :aria-pressed="quiet" @click="quiet=!quiet"><Icon :name="quiet?'Play':'Pause'" :size="13"/>{{quiet?'Resume scene':'Still scene'}}</button></div></section>
<aside class="study-customize"><section class="study-card"><div class="study-card-title"><h2>Make it your own</h2><Icon name="Palette" :size="19"/></div><p>A mood for every kind of day.</p><div class="study-theme-buttons"><button v-for="item in [{id:'calm',label:'Cozy'},{id:'cute',label:'Cute'},{id:'dark',label:'Dark'}]" :class="item.id" :aria-pressed="theme===item.id" @click="chooseTheme(item.id)"><span></span>{{item.label}}<Icon v-if="item.id==='cute'&&!plus" name="LockKeyhole" :size="11"/></button></div><h3>Still wallpapers</h3><div class="study-wallpapers"><button v-for="w in wallpapers" :class="[w.id,{selected:wallpaper===w.id}]" :aria-pressed="wallpaper===w.id" @click="chooseWallpaper(w)"><span class="wallpaper-swatch"><Icon :name="w.id==='night'?'Moon':w.id==='rainy'?'CloudRain':w.id==='blossom'?'Flower2':'Sprout'" :size="25"/><Icon v-if="w.premium&&!plus" class="wallpaper-lock" name="LockKeyhole" :size="11"/></span><strong>{{w.title}}</strong><small>{{w.detail}}</small></button></div><h3>Living backgrounds <span class="badge violet">16 scenes</span></h3><p>Choose one to stream. Sound stays muted.</p><div class="film-picker"><button v-for="(v,i) in videoBackgrounds" :class="{selected:film===v.id}" :aria-pressed="film===v.id" @click="selectFilm(v)"><span>{{String(i+1).padStart(2,'0')}}</span><strong>{{v.title}}</strong><Icon :name="plus?'Play':'LockKeyhole'" :size="14"/></button></div><p v-if="filmError" role="status">{{filmError}}</p></section>
<section class="study-card"><div class="study-card-title"><h2>Sounds for your space</h2><Icon name="Headphones" :size="19"/></div><p>Gentle, original soundscapes. Always optional.</p><label class="sr-only" for="study-sound">Study sound</label><select id="study-sound" v-model="sound" @change="changeSound"><option value="piano">Soft keys · instrumental</option><option value="ambient">Moon garden · ambient</option><option value="rain">Rain at the window</option></select><div class="study-audio-controls"><button class="study-round" :disabled="audioBusy" :aria-label="playing?'Stop study music':'Play study music'" @click="toggleAudio"><Icon :name="playing?'Pause':'Play'" :size="16"/></button><Icon name="Volume2" :size="16"/><input v-model.number="volume" type="range" min="0" max=".7" step=".01" aria-label="Study music volume"/><small>{{Math.round(volume*100)}}%</small></div><small class="study-audio-note">{{playing?'Playing · stops when you pause or finish':'Press play to begin. No autoplay.'}}</small></section>
<div class="study-daily"><Icon name="Coffee" :size="21"/><div><strong>{{total}} {{total===1?'minute':'minutes'}} today</strong><small>From your last 30 saved sessions. Rest counts, too.</small></div></div></aside></div><p v-if="error" class="error" role="alert">{{error}}</p><p class="study-disclosure">Saved in this browser for your current account. The timer keeps time while you’re away; audio stops when you leave Study Room. A sleeping device may delay the completion message.</p>
<div v-if="upgrade" class="study-upgrade-overlay" @click.self="upgrade=false"><section ref="upgradeDialog" role="dialog" aria-modal="true" aria-labelledby="study-upgrade-title" class="study-upgrade"><button class="study-upgrade-close study-round" aria-label="Close Study Plus" @click="upgrade=false"><Icon name="X"/></button><span class="study-pill"><Icon name="Sparkles" :size="14"/>OPTIONAL STUDENT SUBSCRIPTION</span><h2 id="study-upgrade-title">A cozier corner<br>for your curious mind.</h2><p>Study Plus adds music, sixteen living backgrounds, three illustrated wallpapers and a cute theme. Includes a focus timer, stopwatch, breaks and a dark theme.</p><ul><li>Soft keys, ambient music and rain</li><li>16 streaming video backgrounds and illustrated wallpapers</li><li>Gentle animation with pause controls</li></ul><strong>Your assigned price is shown at checkout</strong><p class="study-purchase-note">{{isDemo?'This preview unlocks 30 days locally. No card, payment, subscription contract or automatic renewal is created.':'View your assigned Study Room quote below. Access starts after your subscription is activated.'}}</p><button v-if="!isDemo&&!plus" class="study-start" @click="quoteStudy">View my assigned price</button><div v-if="checkout"><strong>{{checkout.currency}} {{(checkout.breakdown.total_minor/100).toFixed(2)}} · {{checkout.period}}</strong><p>Quote valid for 15 minutes. No payment taken. Subscription payment setup is awaiting provider integration.</p></div><button v-if="isDemo&&!plus" class="study-start" @click="activate">Try 30-day demo access</button><button v-if="plus&&isDemo" class="study-button" @click="endPreview();upgrade=false">End Study Plus preview</button><button class="study-link" @click="upgrade=false">Close</button></section></div></div></template>
<style>
.study-space{--study-ink:#56485f;--study-muted:#817487;--study-card:#fffdfb;--study-border:#e9e0ee;--study-accent:#967bb1;--study-soft:#f2ebf8;color:var(--study-ink)}.study-space.cute{--study-ink:#795562;--study-muted:#977985;--study-card:#fffaf9;--study-border:#f0dce5;--study-accent:#bd849f;--study-soft:#faeaf0}.study-space.dark{--study-ink:#f0e7f4;--study-muted:#bcb0c7;--study-card:#262333;--study-border:#474052;--study-accent:#ac96d0;--study-soft:#373044;background:#1b1925;padding:24px;border-radius:22px}.study-heading{display:flex;justify-content:space-between;align-items:center;gap:20px;margin-bottom:28px}.study-heading h1{font-size:32px;letter-spacing:-1px;margin:9px 0;color:var(--study-ink)}.study-heading p{font-size:13px;color:var(--study-muted);margin:0}.study-heading .eyebrow{color:var(--study-muted)}.study-button,.study-round,.study-start{display:inline-flex;align-items:center;justify-content:center;gap:9px;cursor:pointer;font:inherit}.study-button{border:1px solid var(--study-border);background:var(--study-card);color:var(--study-ink);padding:12px 17px;border-radius:12px;font-size:12px}.study-grid{display:grid;grid-template-columns:minmax(0,1fr) 306px;gap:24px}.study-canvas{position:relative;min-height:780px;border-radius:25px;overflow:hidden;border:1px solid var(--study-border);isolation:isolate}.study-timer-content{position:relative;z-index:1;text-align:center;padding:44px 20px;color:#604e57;background:linear-gradient(#f9f4eebb,#f9f4ee00 90%)}.dark .study-timer-content{color:#f1e4ec;background:linear-gradient(#191d33c9,#191d3300 90%)}.study-pill{display:inline-flex;gap:6px;align-items:center;font-size:9px;font-weight:700;letter-spacing:1.2px;border:1px solid currentColor;border-radius:20px;padding:7px 10px;opacity:.85}.study-topic{display:block;max-width:400px;margin:28px auto 19px}.study-topic input{width:100%;border:0;background:transparent;font:inherit;font-size:16px;color:inherit;text-align:center;padding:6px;border-bottom:1px solid #8a768c35;outline-offset:4px}.study-topic input::placeholder{color:inherit;opacity:.7}.study-modes{display:flex;justify-content:center;gap:4px;flex-wrap:wrap}.study-modes button{border:0;border-radius:20px;padding:9px 12px;background:none;color:inherit;cursor:pointer;font-size:11px}.study-modes button[aria-pressed=true]{background:#fffbf080;box-shadow:0 2px 12px #715e6c0a}.dark .study-modes button[aria-pressed=true]{background:#ffffff1a}.study-clock{font-family:ui-rounded,'Arial Rounded MT Bold','Trebuchet MS',sans-serif;font-size:clamp(42px,6.2vw,96px);font-weight:800;letter-spacing:-4px;font-variant-numeric:tabular-nums;line-height:1.1;margin:23px 0 12px;text-shadow:0 2px 0 #ffffff17}.study-clock-caption{font-size:12px;letter-spacing:.2px}.study-duration{display:flex;gap:6px;align-items:center;justify-content:center;margin:21px auto}.study-duration button,.study-duration label{border:1px solid #846f812b;border-radius:9px;background:#fffbf04d;padding:8px 10px;font-size:10px;color:inherit;cursor:pointer}.study-duration button.chosen{border-color:currentColor}.study-duration label{display:flex;align-items:center;gap:4px;padding:6px}.study-duration input{width:36px;background:none;border:0;color:inherit;font:inherit;appearance:textfield}.dark .study-duration button,.dark .study-duration label{background:#ffffff12}.study-timer-actions{display:flex;align-items:center;justify-content:center;gap:10px;margin-top:23px}.study-start{border:0;padding:14px 26px;background:var(--study-accent);color:#fff;border-radius:14px;font-size:13px;box-shadow:0 7px 20px #76598b20}.dark .study-start{color:#241c33}.study-round{height:43px;width:43px;border:1px solid var(--study-border);border-radius:13px;background:var(--study-card);color:var(--study-ink);flex-shrink:0}.study-status{font-size:11px;min-height:20px;max-width:380px;margin:17px auto}.study-canvas-footer{position:absolute;z-index:2;bottom:16px;left:22px;right:22px;display:flex;align-items:center;justify-content:space-between;color:#6a525d;font-size:9px}.dark .study-canvas-footer{color:#d9ccd9}.study-canvas-footer span,.study-canvas-footer button{display:flex;align-items:center;gap:5px}.study-canvas-footer button{background:transparent;border:0;color:inherit;font-size:9px;cursor:pointer}.study-customize{display:flex;flex-direction:column;gap:17px}.study-card{border:1px solid var(--study-border);background:var(--study-card);padding:21px;border-radius:19px}.study-card-title{display:flex;align-items:center;justify-content:space-between}.study-card h2{font-size:15px;margin:0}.study-card h3{font-size:11px;margin:21px 0 12px}.study-card p{font-size:10px;line-height:1.7;color:var(--study-muted);margin:8px 0 16px}.study-theme-buttons{display:flex;gap:9px}.study-theme-buttons button{flex:1;display:flex;align-items:center;justify-content:center;gap:5px;padding:9px 4px;border:1px solid var(--study-border);border-radius:9px;background:none;color:var(--study-ink);font-size:10px;cursor:pointer}.study-theme-buttons button[aria-pressed=true]{outline:1px solid var(--study-accent);background:var(--study-soft)}.study-theme-buttons span{width:12px;height:12px;border-radius:50%;background:#d6e5dc}.study-theme-buttons .cute span{background:#edb9cf}.study-theme-buttons .dark span{background:#484159}.study-wallpapers{display:grid;grid-template-columns:1fr 1fr;gap:14px 10px}.study-wallpapers button{padding:0;border:0;background:transparent;text-align:start;color:var(--study-ink);cursor:pointer;min-width:0}.wallpaper-swatch{height:66px;position:relative;display:flex;align-items:center;justify-content:center;border:2px solid transparent;border-radius:10px;background:linear-gradient(140deg,#dce9df,#adbfac);color:#65816c}.study-wallpapers .selected .wallpaper-swatch{border-color:var(--study-accent)}.blossom .wallpaper-swatch{background:linear-gradient(140deg,#f8e3e7,#e0b4cb);color:#af7c99}.rainy .wallpaper-swatch{background:linear-gradient(140deg,#d6e0eb,#8da6b8);color:#5c758f}.night .wallpaper-swatch{background:linear-gradient(140deg,