<style>.study-space.dark{--study-ink:#f0dfdf;--study-muted:#c6b2be;--study-card:#302833;--study-border:#51404e;--study-soft:#403142;background:#251f2a}.study-space.dark.immersive{background:#251f2a}.study-space.dark .study-canvas{box-shadow:0 16px 60px #0e0b1555}.study-space.dark .study-timer-content{color:#f2e0de;background:linear-gradient(#2a2039c9,#2a203900 95%)}.study-space.dark .study-clock{text-shadow:0 0 38px #e8bc9320;color:#f1ddd6}.study-space.dark .study-card{box-shadow:0 4px 18px #160f181c}.study-quote{max-width:390px;margin:18px auto 0;padding:14px 20px;border-radius:18px;background:#fffbf080;backdrop-filter:blur(8px);border:1px solid #fff7}.study-quote>svg{opacity:.75}.study-quote p{font-size:13px!important;line-height:1.65!important;color:inherit!important;margin:7px 0 10px}.study-quote>div{display:flex;justify-content:center;gap:13px}.study-quote button{font-size:8px;color:inherit;background:none;border:0;cursor:pointer;padding:3px;text-decoration:underline;text-underline-offset:3px;opacity:.8}.dark .study-quote{background:#44303b73;border-color:#b697b32b;box-shadow:0 5px 30px #140d1a1c}.study-space .study-topic input{background:transparent}.study-space.dark .study-topic input{background:transparent;color:#eddfec}.study-space .study-heading h1{color:var(--study-ink)}.study-space .study-card h2,.study-space .study-card h3,.study-space .study-membership h2{color:var(--study-ink)}.study-canvas{min-height:860px}@media(max-width:600px){.study-canvas{min-height:790px}.study-quote{padding:12px 14px;max-width:290px}.study-quote p{font-size:11px!important}}</style>

<style>
.study-sections{display:flex;flex-direction:row;gap:10px;margin:0 0 25px;flex-wrap:wrap}.study-sections>button{width:auto;display:flex;align-items:center;gap:9px;padding:12px 20px;border-radius:30px;border:1px solid var(--study-border);background:var(--study-card);color:var(--study-ink);font-size:12px}.study-sections>button.chosen{background:var(--study-soft);border-color:var(--study-accent)}.study-film{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;z-index:0}.film-shade{position:absolute;inset:0;background:linear-gradient(#17132335,#17132355);z-index:0}.has-film .study-timer-content{color:#fff5e9!important;background:none!important;text-shadow:0 2px 20px #1b122f99}.has-film .study-timer-content input{color:inherit!important}.has-film .study-clock{color:#fff5e9!important}.has-film .study-quote{color:#fff;background:#251c354d;border-color:#ffffff40}.has-film .study-canvas-footer{color:#fff7eb;background:#251c3555;border-radius:20px;padding:8px 14px}.film-picker{display:grid;gap:7px;max-height:225px;overflow:auto;padding:4px}.film-picker button{display:flex;gap:12px;align-items:center;background:var(--study-soft);border:1px solid transparent;color:var(--study-ink);border-radius:11px;padding:11px;text-align:left;font-size:11px}.film-picker button.selected{border-color:var(--study-accent)}.film-picker strong{flex:1;font-weight:500}.film-picker span{font-size:10px;opacity:.6}.study-space.immersive{padding:0!important;z-index:300;background:#201c26}.immersive .study-heading{position:absolute;z-index:5;top:18px;right:18px;margin:0}.immersive .study-heading>div,.immersive .study-customize,.immersive .study-disclosure{display:none}.immersive .study-grid{display:block;height:100dvh}.immersive .study-canvas{height:100dvh;min-height:100dvh;border:0;border-radius:0;overflow:auto}.immersive .study-timer-content{min-height:100dvh;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:65px 20px}.immersive .study-clock{font-size:clamp